<script setup>
import ProgressOverview from './ProgressOverview.vue';import {Link} from '@inertiajs/vue3';import {date,modes} from '../art';defineProps({stats:Object,admin:Boolean});
const pct=(c,n)=>n?Math.round(c/n*100)+'%':'None yet';
</script><template><div v-if="stats">
<ProgressOverview v-if="stats.scope" :scope="stats.scope" :admin="admin"/>
<details class="panel"><summary>Response and recall details</summary><p>Filtered graded responses: {{stats.graded_correct}} correct / {{stats.graded_total}} responses ({{pct(stats.graded_correct,stats.graded_total)}}). Repeated answers are included.</p><p>Lifetime flashcard reviews: {{stats.flashcard_reviews}}. {{stats.flashcards_due}} cards currently rated 1 or 2. Ratings describe familiarity separately from answer accuracy.</p></details><p v-if="stats.legacy" class="notice">{{stats.legacy}} legacy results were imported. Their historical first-attempt accuracy and study time are unknown.</p>
<details class="panel"><summary>Coverage by subject · selected filters</summary><div v-for="s in stats.scope.coverage" :key="s.subject" class="coverage"><div class="row"><strong>{{s.subject}}</strong><span>{{s.completed}} / {{s.total}}</span></div><div class="meter"><i :style="{width:(s.total?s.completed/s.total*100:0)+'%'}"></i></div></div></details>
<section class="panel"><h2>Subject and topic performance</h2><p v-if="!stats.groups.length">No graded responses match these filters yet.</p><div v-else class="table-wrap"><table><thead><tr><th>Subject / topic</th><th>Correct</th><th>Responses</th><th>Accuracy</th></tr></thead><tbody><tr v-for="g in stats.groups" :key="g.label"><td>{{g.label}}</td><td>{{g.correct}}</td><td>{{g.answered}}</td><td>{{pct(g.correct,g.answered)}} <small v-if="g.answered<5">Small sample</small></td></tr></tbody></table></div></section>
<section class="panel"><h2>Recent attempts</h2><p class="muted">All dates · selected study tool</p><p v-if="!stats.attempts.length">Completed and unfinished rounds will appear here.</p><div class="table-wrap" v-else><table><thead><tr><th>Round</th><th>Status</th><th>Score</th><th>Active time estimate</th><th>Started</th></tr></thead><tbody><tr v-for="a in stats.attempts" :key="a.id"><td><Link v-if="!admin" :href="'/attempts/'+a.id">{{modes[a.mode]}}</Link><span v-else>{{modes[a.mode]}}</span></td><td>{{a.status.replace('_',' ')}}</td><td>{{a.score===null?'In progress':a.score+' / '+a.items_count}}</td><td>{{Math.round(a.active_seconds/60)}} min</td><td>{{date(a.created_at)}}</td></tr></tbody></table></div></section>

</div></template>
